def solve(values: list[float], n_resamples: int = 2000) -> float:
    import random, statistics
    rng = random.Random(42)
    n = len(values)
    # Bootstrap: resample with replacement, compute mean, repeat
    means = [
        statistics.mean(rng.choices(values, k=n))
        for _ in range(n_resamples)
    ]
    # Standard error of mean ≈ std of bootstrap means
    return round(statistics.stdev(means), 6)

