    events = defaultdict(int)
    for t, e in data:
        if e == 1:
            events[t] += 1
    sorted_times = sorted(events.keys())
    S = 1.0
    for t in sorted_times:
        n = sum(1 for obs_t, _ in data if obs_t >= t)  # risk set
        d = events[t]
        S = S * (1 - d / n)  # product-limit update
        if S <= 0.5:  # first crossing of the 50% threshold
